	"o-as-vowel": 44,
	"implicit-o": 60,
	"initial-cluster": 12,
	"w-as-vowel": 14,
	"polysyllabic-implicit-a": 10,
	"ro-han": 6,
	"bare-final-ro": 3,
};

const THREE_CONSONANT_DISTRIBUTION: Readonly<Record<string, number>> = {
	"o-as-vowel": 35,
	"w-as-vowel": 12,
	"polysyllabic-implicit-a": 7,
	"initial-cluster": 4,
	"implicit-o": 3,
};

